/* Delivered cuts remain separate from the editable storyboard. */
const previewSources={};
function deliveredPreview(e){return state.title===PREVIEW_LIBRARY.project?PREVIEW_LIBRARY.episodes[String(e.number)]:null}
function previewData(e){const delivered=deliveredPreview(e),mode=previewSources[e.id]||(delivered?'delivery':'canvas');return {mode,delivered,shots:mode==='delivery'&&delivered?delivered.shots:e.shots,full:mode==='delivery'?delivered?.full:null}}
function episodePreview(e){const d=previewData(e),ready=d.shots.filter(s=>s.video),duration=d.shots.reduce((n,s)=>n+s.duration,0);return `<section class="episode-preview"><header class="preview-heading"><div><div class="eyebrow">EPISODE SCREENING</div><h3>第${String(e.number).padStart(2,'0')}集 · ${esc(d.mode==='delivery'?d.delivered.title:e.title)}</h3><p>${d.shots.length} 个镜头 · ${ready.length} 个视频可播放 · 分镜设定 ${duration} 秒</p></div><label>预览版本<select id="previewSource">${d.delivered?'<option value="delivery" '+(d.mode==='delivery'?'selected':'')+'>已交付视频版本</option>':''}<option value="canvas" ${d.mode==='canvas'?'selected':''}>当前制作画布</option></select></label></header>${d.mode==='delivery'?'<p class="preview-note">来自本地交付“视频总览”，保留该版镜头顺序与台词。当前分镜编辑不会自动改动这份视频。</p>':'<p class="preview-note">显示本集画布已有的视频。未生成镜头保留占位；顺序播放仅串播现有片段，不代表已合成整集。</p>'}<div class="preview-full"><div class="preview-player-title"><h3>${d.full?'整集顺序预览':'镜头顺序播放'}</h3>${d.full?`<a href="${src(d.full)}" download>下载整集 ↓</a>`:''}</div>${d.full||ready.length?`<video id="episodePlayer" controls playsinline preload="metadata" src="${src(d.full||ready[0].video)}"></video>${d.full?'':`<div class="preview-transport"><button id="previewPrev">← 上一镜</button><span id="previewNow">${esc(ready[0].title)}</span><button id="previewNext">下一镜 →</button></div>`}`:'<div class="preview-empty"><b>本集还没有可播放的视频</b><p>在制作画布生成并取回视频后，即可在这里预览。</p><button id="previewToCanvas">进入制作画布 ↗</button></div>'}<p id="previewPlaybackMessage" role="status"></p></div><div class="preview-grid">${d.shots.map((s,i)=>`<article><div class="preview-cover">${s.video?`<video controls playsinline preload="none" ${s.image?`poster="${src(s.image)}"`:''} src="${src(s.video)}"></video>`:`${s.image?`<img loading="lazy" src="${src(s.image)}" alt="${esc(s.title)}">`:''}<span>视频待生成</span>`}</div><div class="preview-caption"><h4>${/^S\d+/.test(s.title)?'':`S${String(i+1).padStart(2,'0')} · `}${esc(s.title)}<small>${s.duration}秒</small></h4><p>${esc(s.dialogue||'无对白')}</p>${s.video?`<a href="${src(s.video)}" download>下载本镜 ↓</a>`:'<small>暂无视频</small>'}</div></article>`).join('')}</div></section>`}
function bindEpisodePreview(){if(page!=='episodes'||tab!=='preview')return;const e=current(),d=previewData(e),ready=d.shots.filter(s=>s.video),player=$('#episodePlayer');$('#previewSource').onchange=()=>{previewSources[e.id]=$('#previewSource').value;render()};on('#previewToCanvas',()=>syncCanvas());const videos=$$('.episode-preview video');videos.forEach(v=>{v.onplay=()=>videos.forEach(other=>{if(other!==v)other.pause()});v.onerror=()=>{const msg=$('#previewPlaybackMessage');if(msg)msg.textContent='视频文件暂时无法播放，请检查文件是否存在或格式是否受浏览器支持。'}});if(!d.full&&player){let index=0;function select(i,play){index=Math.max(0,Math.min(ready.length-1,i));player.src=src(ready[index].video);$('#previewNow').textContent=`${index+1} / ${ready.length} · ${ready[index].title}`;$('#previewPrev').disabled=index===0;$('#previewNext').disabled=index===ready.length-1;if(play)player.play().catch(()=>{$('#previewPlaybackMessage').textContent='点击播放按钮继续观看。'})}on('#previewPrev',()=>select(index-1,true));on('#previewNext',()=>select(index+1,true));player.onended=()=>{if(index<ready.length-1)select(index+1,true);else $('#previewPlaybackMessage').textContent='已播放完本集现有视频。'};$('#previewPrev').disabled=true;$('#previewNext').disabled=ready.length<=1}}
const bodyBeforePreview=episodeBody;episodeBody=function(e){return tab==='preview'?episodePreview(e):bodyBeforePreview(e)};
const bindBeforePreview=bindPage;bindPage=function(){bindBeforePreview();bindEpisodePreview()};
